create schema if not exists private;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role_id uuid not null references public.roles(id) on delete restrict, display_name text not null, avatar_url text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create or replace function private.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ declare default_role_id uuid; begin select id into default_role_id from public.roles where code = 'student' limit 1; if default_role_id is null then raise exception 'Default student role does not exist'; end if; insert into public.profiles (id, role_id, display_name) values (new.id, default_role_id, coalesce(nullif(new.raw_user_meta_data ->> 'display_name', ''), nullif(new.raw_user_meta_data ->> 'full_name', ''), split_part(coalesce(new.email, 'Student'), '@', 1))); return new; end; $$;
revoke execute on function private.handle_new_user() from public, anon, authenticated;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();;
